                        int idxHora = reader.GetOrdinal("hora_cita");

                        if (!reader.IsDBNull(idxHora))
                        {
                            TimeSpan hora = reader.GetTimeSpan(idxHora);

                            cita.hora_cita_mostrar = DateTime.Today.Add(hora).ToString("hh:mm tt");
